<?php $q=new WP_Query(['post_type'=>'program','posts_per_page'=>(int)($attributes['count']??6)]); ?><section class="sb-section alignfull sb-section--pale"><div class="sb-container"><h2><?php echo wp_kses_post($attributes['heading']??'Programs'); ?></h2><div class="sb-program-grid"><?php while($q->have_posts()):$q->the_post();?><article class="sb-program-card"><?php if(has_post_thumbnail()) the_post_thumbnail('large');?><div><p class="sb-eyebrow"><?php $terms=get_the_terms(get_the_ID(),'program_type'); echo esc_html($terms&&!is_wp_error($terms)?$terms[0]->name:'Program'); ?></p><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><p><?php echo esc_html(get_post_meta(get_the_ID(),'sb_tagline',true) ?: get_the_excerpt()); ?></p><a class="sb-text-link" href="<?php the_permalink(); ?>">Learn more →</a></div></article><?php endwhile;wp_reset_postdata();?></div></div></section>
